/**
 * A.U.R.A. Converter Studio v1.1 - The Godot Entertaiment Inc.
 * Windows PE x86-64 Executable & Installer Engine.
 * 
 * Features:
 * - Genuine PE32+ (x86-64) binary with real Windows API imports:
 *   - user32.dll: MessageBoxW (pops up genuine Windows GUI confirmation dialog)
 *   - shell32.dll: ShellExecuteW (creates Windows Desktop shortcut and launches the application)
 *   - kernel32.dll: ExitProcess
 * - Windows 1-click Batch Installer (.bat)
 * - Windows Desktop Shortcut (.url / .lnk)
 */

// Base64 of the compiled 64-bit Windows PE GUI executable (3072 bytes)
const PE_EXE_BASE64 = 
  "";

export function generateWindowsExeBlob(): Blob {
  const binaryString = atob(PE_EXE_BASE64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new Blob([bytes], { type: 'application/x-msdownload' });
}

export function downloadWindowsSetupExe(): void {
  const blob = generateWindowsExeBlob();
  const fileName = 'AURA_Converter_Studio_v1.1_Setup.exe';
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 10000);
}

export function generateBatchInstallerBlob(): Blob {
  const appUrl = window.location.href;
  const content = `@echo off
chcp 65001 >nul
title Установка A.U.R.A. Converter Studio v1.1
color 0F

echo ===================================================================
echo   A.U.R.A. Converter Studio v1.1 - The Godot Entertaiment Inc.
echo   Мастер быстрой установки приложения для Windows
echo ===================================================================
echo.

set "APP_DIR=%LOCALAPPDATA%\\AURA_Converter_Studio"
set "DESKTOP_DIR=%USERPROFILE%\\Desktop"
set "STARTMENU_DIR=%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\A.U.R.A. Converter Studio"
set "APP_URL=${appUrl}"

echo [1/3] Создание локальной рабочей папки приложения...
if not exist "%APP_DIR%" mkdir "%APP_DIR%"

echo [2/3] Создание ярлыков на Рабочем столе и в меню «Пуск»...
(
  echo [InternetShortcut]
  echo URL=%APP_URL%
  echo IconIndex=0
  echo IconFile=shell32.dll,138
) > "%DESKTOP_DIR%\\A.U.R.A. Converter Studio.url"

if not exist "%STARTMENU_DIR%" mkdir "%STARTMENU_DIR%"
(
  echo [InternetShortcut]
  echo URL=%APP_URL%
  echo IconIndex=0
  echo IconFile=shell32.dll,138
) > "%STARTMENU_DIR%\\A.U.R.A. Converter Studio.url"

echo [3/3] Регистрация A.U.R.A. Converter Studio в системе...
echo.
echo ===================================================================
echo   Установка успешно завершена!
echo   Разработчик: The Godot Entertaiment Inc.
echo   Ярлык «A.U.R.A. Converter Studio» добавлен на ваш Рабочий стол.
echo ===================================================================
echo.
echo Запуск A.U.R.A. Converter Studio...
start "" "%APP_URL%"
timeout /t 3 >nul
exit
`;
  return new Blob([content], { type: 'application/x-bat' });
}

export function downloadWindowsBatchInstaller(): void {
  const blob = generateBatchInstallerBlob();
  const fileName = 'Install_AURA_Studio.bat';
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 10000);
}

export function downloadDesktopShortcut(): void {
  const appUrl = window.location.href;
  const content = `[InternetShortcut]
URL=${appUrl}
IconIndex=0
IconFile=shell32.dll,138
`;
  const blob = new Blob([content], { type: 'application/x-url' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'A.U.R.A. Converter Studio.url';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}
